#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    vector<bool> seen(26, false);  // 标记字母 a~z 是否已扫描过
    char prev = 0;                  // 前一个字符，0 表示无
    long long total = 0;            // 总消耗点数

    for (char c : s) {
        char lower = tolower(c);
        int idx = lower - 'a';
        // 基础消耗
        if (!seen[idx]) {
            total += 500;
            seen[idx] = true;
        } else {
            total += 100;
        }
        // 额外消耗
        if (prev) {
            if (c == prev) {
                total += 23;
            } else if (abs(lower - tolower(prev)) == 1) {
                total += 44;
            }
        }
        prev = c;
    }

    cout << total << "\n";
    return 0;
}
